export interface ConnectorConfig {
  /** Google OAuth client ID */
  googleClientId: string
  /** Google OAuth client secret */
  googleClientSecret: string
  /** Stored Google OAuth refresh token */
  googleRefreshToken: string
  /** Google Sheets spreadsheet ID */
  spreadsheetId: string
  /** Google Sheets range (e.g., "Sheet1!A:A") */
  sheetRange: string
  /** Injected fetch for testing */
  fetch?: typeof fetch
}

export interface HubSpotDealWebhookPayload {
  objectId: string
  properties: {
    dealstage: string
  }
  subscriptionType: string
  portalId: string
  eventId: string
}

export interface TokenRefreshResponse {
  access_token: string
  expires_in: number
  scope: string
  token_type: string
}

export interface SheetsAppendResponse {
  spreadsheetId: string
  tableRange: string
  updates: {
    spreadsheetId: string
    updatedRange: string
    updatedRows: number
    updatedColumns: number
    updatedCells: number
  }
}

export interface HandleResult {
  dealId: string
  dealStage: string
  accessToken: string
  sheetsResponse: SheetsAppendResponse
}

async function refreshAccessToken(config: ConnectorConfig): Promise<string> {
  const fetchFn = config.fetch ?? fetch
  const body = new URLSearchParams({
    client_id: config.googleClientId,
    client_secret: config.googleClientSecret,
    refresh_token: config.googleRefreshToken,
    grant_type: 'refresh_token',
  })

  const response = await fetchFn('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: body.toString(),
  })

  if (!response.ok) {
    throw new Error(`Token refresh failed: ${response.status} ${response.statusText} at https://oauth2.googleapis.com/token`)
  }

  const data = (await response.json()) as TokenRefreshResponse
  return data.access_token
}

async function appendToSheets(
  accessToken: string,
  spreadsheetId: string,
  sheetRange: string,
  dealStage: string,
  fetchFn: typeof fetch,
): Promise<SheetsAppendResponse> {
  const url = `https://sheets.googleapis.com/v4/spreadsheets/${encodeURIComponent(spreadsheetId)}/values/${encodeURIComponent(sheetRange)}:append`
  const body = JSON.stringify({
    values: [[dealStage]],
  })

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(`Sheets append failed: ${response.status} ${response.statusText} at ${url}`)
  }

  return (await response.json()) as SheetsAppendResponse
}

export async function handle(
  payload: HubSpotDealWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  if (!payload.objectId) {
    throw new Error('Missing required field: objectId')
  }
  if (!payload.properties?.dealstage) {
    throw new Error('Missing required field: properties.dealstage')
  }
  if (!payload.subscriptionType) {
    throw new Error('Missing required field: subscriptionType')
  }
  if (!config.googleClientId) {
    throw new Error('Missing config: googleClientId')
  }
  if (!config.googleClientSecret) {
    throw new Error('Missing config: googleClientSecret')
  }
  if (!config.googleRefreshToken) {
    throw new Error('Missing config: googleRefreshToken')
  }
  if (!config.spreadsheetId) {
    throw new Error('Missing config: spreadsheetId')
  }
  if (!config.sheetRange) {
    throw new Error('Missing config: sheetRange')
  }

  const dealStage = payload.properties.dealstage
  const accessToken = await refreshAccessToken(config)
  const sheetsResponse = await appendToSheets(
    accessToken,
    config.spreadsheetId,
    config.sheetRange,
    dealStage,
    config.fetch ?? fetch,
  )

  return {
    dealId: payload.objectId,
    dealStage,
    accessToken,
    sheetsResponse,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, HubSpotDealWebhookPayload } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      googleClientId: 'test-client-id',
      googleClientSecret: 'test-client-secret',
      googleRefreshToken: 'test-refresh-token',
      spreadsheetId: '1BxiMVs0XRA5nFMdKvBdBZjgmUUqptlbs74OgvE2upms',
      sheetRange: "Sheet1!A:A",
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.dealId).toBe('12345')
    expect(result.dealStage).toBe('qualified_to_buy')
    expect(result.accessToken).toBe('ya29.a0AfH6SMC...')
  })
})

describe('handle', () => {
  it('validates required payload fields', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const baseConfig: ConnectorConfig = {
      googleClientId: 'cid',
      googleClientSecret: 'csecret',
      googleRefreshToken: 'rtoken',
      spreadsheetId: 'sid',
      sheetRange: 'Sheet1!A:A',
      fetch,
    }

    await expect(handle({} as HubSpotDealWebhookPayload, baseConfig)).rejects.toThrow('Missing required field: objectId')
    await expect(handle({ objectId: '1' } as HubSpotDealWebhookPayload, baseConfig)).rejects.toThrow('Missing required field: properties.dealstage')
    await expect(handle({ objectId: '1', properties: { dealstage: 'x' } } as HubSpotDealWebhookPayload, baseConfig)).rejects.toThrow('Missing required field: subscriptionType')
  })

  it('validates required config fields', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload

    await expect(handle(payload, { ...{ googleClientId: '', googleClientSecret: 's', googleRefreshToken: 'r', spreadsheetId: 'id', sheetRange: 'r' }, fetch })).rejects.toThrow('Missing config: googleClientId')
    await expect(handle(payload, { ...{ googleClientId: 'c', googleClientSecret: '', googleRefreshToken: 'r', spreadsheetId: 'id', sheetRange: 'r' }, fetch })).rejects.toThrow('Missing config: googleClientSecret')
    await expect(handle(payload, { ...{ googleClientId: 'c', googleClientSecret: 's', googleRefreshToken: '', spreadsheetId: 'id', sheetRange: 'r' }, fetch })).rejects.toThrow('Missing config: googleRefreshToken')
    await expect(handle(payload, { ...{ googleClientId: 'c', googleClientSecret: 's', googleRefreshToken: 'r', spreadsheetId: '', sheetRange: 'r' }, fetch })).rejects.toThrow('Missing config: spreadsheetId')
    await expect(handle(payload, { ...{ googleClientId: 'c', googleClientSecret: 's', googleRefreshToken: 'r', spreadsheetId: 'id', sheetRange: '' }, fetch })).rejects.toThrow('Missing config: sheetRange')
  })

  it('calls token endpoint with correct form body and gets access token', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://oauth2.googleapis.com/token') {
        return jsonResponse({ access_token: 'new-access-token', expires_in: 3600, scope: 'scope', token_type: 'Bearer' }, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      googleClientId: 'my-client-id',
      googleClientSecret: 'my-client-secret',
      googleRefreshToken: 'my-refresh-token',
      spreadsheetId: 'sheet-123',
      sheetRange: 'Sheet1!A:A',
      fetch,
    }

    await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config)

    const tokenCall = calls.find((c) => c.url === 'https://oauth2.googleapis.com/token')
    expect(tokenCall).toBeDefined()
    expect(tokenCall?.method).toBe('POST')
    expect(tokenCall?.headers.get('content-type')).toBe('application/x-www-form-urlencoded')
    const bodyParams = new URLSearchParams(tokenCall?.body ?? '')
    expect(bodyParams.get('client_id')).toBe('my-client-id')
    expect(bodyParams.get('client_secret')).toBe('my-client-secret')
    expect(bodyParams.get('refresh_token')).toBe('my-refresh-token')
    expect(bodyParams.get('grant_type')).toBe('refresh_token')
  })

  it('calls sheets append with bearer token and deal stage value', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://oauth2.googleapis.com/token') {
        return jsonResponse({ access_token: 'sheet-access-token', expires_in: 3600, scope: 'scope', token_type: 'Bearer' }, 200)
      }
      if (req.url.includes('/spreadsheets/') && req.url.includes(':append')) {
        return jsonResponse({
          spreadsheetId: 'sheet-123',
          tableRange: "'Sheet1'!A2:A2",
          updates: { spreadsheetId: 'sheet-123', updatedRange: "'Sheet1'!A2:A2", updatedRows: 1, updatedColumns: 1, updatedCells: 1 },
        }, 200)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      googleClientId: 'cid',
      googleClientSecret: 'csecret',
      googleRefreshToken: 'rtoken',
      spreadsheetId: 'sheet-123',
      sheetRange: 'Sheet1!A:A',
      fetch,
    }

    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config)

    const sheetsCall = calls.find((c) => c.url.includes(':append'))
    expect(sheetsCall).toBeDefined()
    expect(sheetsCall?.method).toBe('POST')
    expect(sheetsCall?.headers.get('authorization')).toBe('Bearer sheet-access-token')
    expect(sheetsCall?.headers.get('content-type')).toBe('application/json')
    expect(sheetsCall?.json).toEqual({ values: [['qualified_to_buy']] })
    expect(result.sheetsResponse.updates.updatedRows).toBe(1)
  })

  it('throws on non-2xx token response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://oauth2.googleapis.com/token') {
        return jsonResponse({ error: 'invalid_grant' }, 400)
      }
      return jsonResponse({}, 200)
    })

    const config: ConnectorConfig = {
      googleClientId: 'cid',
      googleClientSecret: 'csecret',
      googleRefreshToken: 'rtoken',
      spreadsheetId: 'sid',
      sheetRange: 'Sheet1!A:A',
      fetch,
    }

    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config)).rejects.toThrow('Token refresh failed: 400 Bad Request at https://oauth2.googleapis.com/token')
  })

  it('throws on non-2xx sheets response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://oauth2.googleapis.com/token') {
        return jsonResponse({ access_token: 'token', expires_in: 3600, scope: 'scope', token_type: 'Bearer' }, 200)
      }
      if (req.url.includes(':append')) {
        return jsonResponse({ error: 'not found' }, 404)
      }
      return jsonResponse({}, 200)
    })

    const config: ConnectorConfig = {
      googleClientId: 'cid',
      googleClientSecret: 'csecret',
      googleRefreshToken: 'rtoken',
      spreadsheetId: 'sid',
      sheetRange: 'Sheet1!A:A',
      fetch,
    }

    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealWebhookPayload, config)).rejects.toThrow('Sheets append failed: 404 Not Found at')
  })
})

